// Generic recursive tree template
function solve(node) {
  if (node === null) return 0; // replace with appropriate base value

  const leftResult = solve(node.left);
  const rightResult = solve(node.right);

  return 1 + Math.max(leftResult, rightResult); // example: height
}

// Level-order traversal (BFS template)
function levelOrder(root) {
  if (!root) return [];
  const result = [];
  const queue = [root];

  while (queue.length > 0) {
    const levelSize = queue.length; // snapshot current level size
    const level = [];

    for (let i = 0; i < levelSize; i++) {
      const node = queue.shift();
      level.push(node.val);
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
    result.push(level);
  }
  return result;
}

// Diameter / max-path pattern: global max updated at each node
function diameterOfBinaryTree(root) {
  let maxDiameter = 0;

  function height(node) {
    if (node === null) return 0;
    const left = height(node.left);
    const right = height(node.right);
    maxDiameter = Math.max(maxDiameter, left + right); // diameter through this node
    return 1 + Math.max(left, right); // return height (one-sided) to parent
  }

  height(root);
  return maxDiameter;
}
